<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/reports.php';$current=tuman_require_role('ADMIN');$db=tuman_database();$error=null;$f=['from'=>date('Y-m-01'),'to'=>date('Y-m-t')];$from=trim((string)($_GET['from']??$f['from']));$to=trim((string)($_GET['to']??$f['to']));if(!tuman_invoice_valid_date($from)||!tuman_invoice_valid_date($to)||$from>$to){$error='Choose a valid date range.';}else{$f=['from'=>$from,'to'=>$to];}$teachers=tuman_admin_teachers($db);$chosen=filter_var($_GET['teacher_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($chosen&& !array_filter($teachers,fn($t)=>(int)$t['id']===(int)$chosen)){$error='Teacher is unavailable.';$chosen=null;}$summaries=tuman_admin_teacher_summary($db,$f,$chosen?(int)$chosen:null);tuman_admin_page_start('Teacher reports');?><h1>Teacher reports</h1><p>Administrative summaries use the recorded invoice, payment, credit, and refund ledger. Currency totals remain separate.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="get"><p><label>From <input type="date" name="from" value="<?=htmlspecialchars($f['from'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>To <input type="date" name="to" value="<?=htmlspecialchars($f['to'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Teacher <select name="teacher_id"><option value="">All teachers</option><?php foreach($teachers as $t):?><option value="<?=(int)$t['id']?>"<?=$chosen==$t['id']?' selected':''?>><?=htmlspecialchars(trim($t['first_name'].' '.($t['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><button>Apply filters</button> <a class="button" href="/Tuman/admin/reports.php">Clear</a></p></form><?php if($summaries===[]):?><p>No teachers match the selected filter.</p><?php else:?><div style="overflow-x:auto"><table><thead><tr><th>Teacher</th><th>Email</th><th>Students<br>active / inactive</th><th>Invoices raised</th><th>Payments received</th><th>Refunds</th><th>Outstanding invoices</th></tr></thead><tbody><?php foreach($summaries as $s):$invoiceRows=$s['invoices'];$paymentRows=$s['payments'];$refundRows=$s['refunds'];$out=[];foreach($s['outstanding'] as $i){$code=$i['currency_code'];$due=(tuman_invoice_minor_from_decimal($i['total_amount'])??0)-(tuman_invoice_minor_from_decimal($i['payments'])??0)-(tuman_invoice_minor_from_decimal($i['credits'])??0)+(tuman_invoice_minor_from_decimal($i['refunds'])??0);$out[$code]=($out[$code]??0)+max(0,$due);}$outRows=[];foreach($out as $code=>$minor)$outRows[]=['currency_code'=>$code,'amount'=>tuman_invoice_decimal_from_minor($minor)];?><tr><td><?=htmlspecialchars(trim($s['first_name'].' '.($s['last_name']??'')),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($s['email']??'—',ENT_QUOTES,'UTF-8')?></td><td><?= (int)$s['active_students']?> / <?= (int)$s['inactive_students']?></td><td><?=tuman_report_label($invoiceRows)?></td><td><?=tuman_report_label($paymentRows)?></td><td><?=tuman_report_label($refundRows)?></td><td><?=tuman_report_label($outRows)?></td></tr><?php endforeach;?></tbody></table></div><?php endif;tuman_admin_page_end();?>
